var a=[{title:`Cosa offrono le macchine`,text:`Le macchine a selettore spesso guidano il percorso del movimento e possono ridurre quanto devi bilanciarti. Questo può aiutare un principiante a concentrarsi sullo spingere o tirare con controllo. Alcune macchine si adattano meglio a certe corporature, quindi un percorso guidato non è comodo per tutti.`},{title:`Imposta la postazione`,text:`Regola l’altezza del sedile, lo schienale e i cuscinetti in modo che l’articolazione che lavora sia allineata abbastanza bene alle parti in movimento e che tu raggiunga l’impugnatura senza sforzo. Fai una serie di prova leggera prima di scegliere il carico di lavoro. Tieni le mani lontane dal blocco dei pesi, dai punti di schiacciamento e dai bracci in movimento, e abbassa la resistenza lentamente. Le palestre hanno attrezzature diverse, quindi controlla la macchina o la stazione al cavo precisa che hai e passa a un’opzione con pesi liberi, elastici o a corpo libero se non riesci a regolare la macchina in modo comodo.`},{title:`Come differiscono i cavi`,text:`I sistemi a cavo ti permettono di tirare da più direzioni, con la tensione lungo la linea del cavo. Funzionano bene per rematori, lat machine, distensioni ed esercizi anti-rotazione. La resistenza del cavo non è esattamente costante a ogni angolo dell’articolazione, perché leva e direzione del cavo cambiano durante il movimento.`},{title:`Confrontare gli strumenti`,text:`I pesi liberi ti chiedono di stabilizzare di più il carico da solo, mentre le macchine possono rendere alcuni esercizi più facili da imparare o da caricare con precisione. Entrambi possono sviluppare forza e dimensione muscolare quando sforzo e progressione sono giusti. Una macchina non protegge automaticamente un’articolazione infortunata o dolorante. Se i sintomi persistono, rivolgiti a un medico o a un fisioterapista.`}];var o=[{label:`Mayo Clinic: pesi liberi e macchine a confronto`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Mayo Clinic: tecnica dell’allenamento coi pesi (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};